using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using Relatude.DB.Datamodels;
using Relatude.DB.Datamodels.Properties;

namespace Relatude.DB.NodeServer.ModelEditor;

/// <summary>
/// What the datamodel editor knows about the fields of a node type, a relation, a property and a
/// source beyond their CLR shape: labels, inline help, grouping and the editor to use where the type
/// alone does not say (a Guid that is a node type, a list of Guids that are node types). The shape
/// itself - which fields exist, their kinds, their defaults - comes from reflection over the model
/// classes, so a field added to a model class shows up here without anyone remembering to add it,
/// under "Advanced" with a label made from its name until it gets a catalog entry.
///
/// The same idea as <see cref="Settings.SettingsCatalog"/>, for the model classes. Field paths are the
/// JSON property names <see cref="DatamodelJson"/> writes, which the editor edits directly.
/// </summary>
public static class DatamodelCatalog {

    public sealed class FieldDefinition {
        public required string Path { get; init; }
        public required string Label { get; init; }
        public required string Help { get; init; }
        /// <summary>text, textarea, integer, number, toggle, tristate (a bool that may be unset), choice,
        /// guid, typeRef, typeRefs, relationRef, propertyRef, sourceRef, stringList, intList.</summary>
        public required string Editor { get; init; }
        public required string Group { get; init; }
        public int Order { get; init; }
        public string[]? Choices { get; init; }
        public JsonNode? Default { get; init; }
        public bool Optional { get; init; }
        public bool ReadOnly { get; init; }
    }
    sealed class Entry {
        public required string Label { get; init; }
        public required string Help { get; init; }
        public string Group { get; init; } = "General";
        public int Order { get; init; } = 100;
        public string? Editor { get; init; }
        public bool ReadOnly { get; init; }
    }
    public sealed class PropertyTypeDefinition {
        public required string Value { get; init; }
        public required string Label { get; init; }
        public required string Help { get; init; }
        public required string Group { get; init; }
    }

