    static readonly Lazy<object> schema = new(build);
    /// <summary>The whole schema, built once; it only depends on the model classes.</summary>
    public static object Schema => schema.Value;

    static object build() {
        var common = fields(typeof(PropertyModel), property, hiddenPropertyFields, null);
        var commonPaths = common.Select(f => f.Path).ToHashSet();
        var byType = new Dictionary<string, FieldDefinition[]>();
        foreach (var pt in propertyTypes) {
            var type = PropertyModelJsonConverter.GetModelType(Enum.Parse<PropertyType>(pt.Value));
            byType[pt.Value] = fields(type, property, hiddenPropertyFields, commonPaths);
        }
        return new {
            NodeType = fields(typeof(NodeTypeModel), nodeType, hiddenNodeTypeFields, null),
            Relation = fields(typeof(RelationModel), relation, hiddenRelationFields, null),
            PropertyCommon = common,
            PropertyByType = byType,
            PropertyTypes = propertyTypes,
            Source = fields(typeof(DatamodelSource), source, hiddenSourceFields, null),
            Groups = new[] { "General", "Indexing", "Text search", "Constraints", "System members", "Access", "Code", "Advanced" },
        };
    }

    /// <summary>The catalogued names for a class, so a test can check the catalog against the class.</summary>
    public static IEnumerable<string> CataloguedPaths(Type type) {
        var entries = type == typeof(NodeTypeModel) ? nodeType : type == typeof(RelationModel) ? relation : type == typeof(DatamodelSource) ? source : property;
        return entries.Keys;
    }
    public static IEnumerable<string> HiddenPaths(Type type) {
        return type == typeof(NodeTypeModel) ? hiddenNodeTypeFields : type == typeof(RelationModel) ? hiddenRelationFields : type == typeof(DatamodelSource) ? hiddenSourceFields : hiddenPropertyFields;
    }

    static FieldDefinition[] fields(Type type, Dictionary<string, Entry> entries, HashSet<string> hidden, HashSet<string>? exclude) {
        object? instance = null;
        try { instance = Activator.CreateInstance(type); } catch { }
        var list = new List<FieldDefinition>();
        foreach (var p in type.GetProperties(BindingFlags.Public | BindingFlags.Instance)) {
            if (hidden.Contains(p.Name) || exclude != null && exclude.Contains(p.Name)) continue;
            if (p.GetIndexParameters().Length > 0) continue;
            if (p.SetMethod == null || !p.SetMethod.IsPublic) continue;
            if (p.GetCustomAttribute<System.Text.Json.Serialization.JsonIgnoreAttribute>() != null) continue;
            var valueType = Nullable.GetUnderlyingType(p.PropertyType) ?? p.PropertyType;
            var isNullable = Nullable.GetUnderlyingType(p.PropertyType) != null || !p.PropertyType.IsValueType;
            entries.TryGetValue(p.Name, out var entry);
            var editor = entry?.Editor ?? editorFor(p.PropertyType, valueType);
            JsonNode? defaultValue = null;
            if (instance != null) {
                try { defaultValue = JsonSerializer.SerializeToNode(p.GetValue(instance), p.PropertyType, DatamodelJson.Options); } catch { }
            }
            list.Add(new FieldDefinition {
                Path = p.Name,
                Label = entry?.Label ?? humanize(p.Name),
                Help = entry?.Help ?? "",
                Editor = editor,
                Group = entry?.Group ?? "Advanced",
                Order = entry?.Order ?? 100,
                Choices = valueType.IsEnum ? Enum.GetNames(valueType) : null,
                Default = defaultValue,
                Optional = isNullable,
                ReadOnly = entry?.ReadOnly ?? false,
            });
        }
        return list.OrderBy(f => Array.IndexOf(groupOrder, f.Group) is var i && i < 0 ? 99 : i).ThenBy(f => f.Order).ThenBy(f => f.Label).ToArray();
    }
    static readonly string[] groupOrder = ["General", "Indexing", "Text search", "Constraints", "System members", "Access", "Code", "Advanced"];
    static string editorFor(Type declared, Type valueType) {
        if (valueType == typeof(bool)) return Nullable.GetUnderlyingType(declared) != null ? "tristate" : "toggle";
        if (valueType == typeof(int) || valueType == typeof(long) || valueType == typeof(short) || valueType == typeof(byte)) return "integer";
        if (valueType == typeof(double) || valueType == typeof(float) || valueType == typeof(decimal)) return "number";
        if (valueType == typeof(string)) return "text";
        if (valueType == typeof(Guid)) return "guid";
        if (valueType.IsEnum) return "choice";
        if (valueType == typeof(List<Guid>) || valueType == typeof(Guid[])) return "typeRefs";
        if (valueType == typeof(List<string>) || valueType == typeof(string[])) return "stringList";
        if (valueType == typeof(int[]) || valueType == typeof(List<int>)) return "intList";
        if (valueType == typeof(DateTime) || valueType == typeof(DateTimeOffset) || valueType == typeof(TimeSpan)) return "text";
        return "text";
    }
    static string humanize(string name) {
        var sb = new System.Text.StringBuilder();
        for (var i = 0; i < name.Length; i++) {
            var c = name[i];
            if (i > 0 && char.IsUpper(c) && !char.IsUpper(name[i - 1])) sb.Append(' ');
            sb.Append(i == 0 ? c : char.ToLowerInvariant(c));
        }
        return sb.ToString();
    }
}
